<h4 class="mb-3">Purchase Invoices</h4><div class="card"><div class="table-responsive"><table class="table table-sm mb-0"><thead class="table-light"><tr><th>Invoice</th><th>Supplier inv</th><th>Date</th><th>Due</th><th>Supplier</th><th class="text-end">Total</th><th class="text-end">Balance</th><th>Status</th></tr></thead><tbody>
